package com.example

/**
 * Curated, 100% syllabus-aligned, distinct Flashcards for Civics (පුරවැසි අධ්‍යාපනය).
 * Part 1: Categories 1 to 10 (20 distinct questions per category).
 * Strictly guarantees no repeated questions within the same category or across different categories.
 */
object FlashcardBankCivicsSetsPart1 {

  fun getCard(setNum: Int, cardNum: Int, grade: String): CardContentTuple? {
    val c = cardNum.coerceIn(1, 20)
    return when (setNum) {
      1 -> if (grade == "11") set1_Grade11[(c - 1) % set1_Grade11.size] else set1_Grade10[(c - 1) % set1_Grade10.size]
      2 -> if (grade == "11") set2_Grade11[(c - 1) % set2_Grade11.size] else set2_Grade10[(c - 1) % set2_Grade10.size]
      3 -> if (grade == "11") set3_Grade11[(c - 1) % set3_Grade11.size] else set3_Grade10[(c - 1) % set3_Grade10.size]
      4 -> if (grade == "11") set4_Grade11[(c - 1) % set4_Grade11.size] else set4_Grade10[(c - 1) % set4_Grade10.size]
      5 -> if (grade == "11") set5_Grade11[(c - 1) % set5_Grade11.size] else set5_Grade10[(c - 1) % set5_Grade10.size]
      6 -> if (grade == "11") set6_Grade11[(c - 1) % set6_Grade11.size] else set6_Grade10[(c - 1) % set6_Grade10.size]
      7 -> if (grade == "11") set7_Grade11[(c - 1) % set7_Grade11.size] else set7_Grade10[(c - 1) % set7_Grade10.size]
      8 -> if (grade == "11") set8_Grade11[(c - 1) % set8_Grade11.size] else set8_Grade10[(c - 1) % set8_Grade10.size]
      9 -> if (grade == "11") set9_Grade11[(c - 1) % set9_Grade11.size] else set9_Grade10[(c - 1) % set9_Grade10.size]
      10 -> if (grade == "11") set10_Grade11[(c - 1) % set10_Grade11.size] else set10_Grade10[(c - 1) % set10_Grade10.size]
      else -> FlashcardBankCivicsSetsPart2.getCard(setNum, cardNum, grade)
    }
  }

  // --- SET 1: ප්‍රජාතන්ත්‍රවාදය & මූලික ලක්ෂණ ---

  // --- SET 2: ආණ්ඩුක්‍රම ව්‍යවස්ථාව & නීතියේ ආධිපත්‍යය ---

  // --- SET 3: ව්‍යවස්ථාදායකය (පාර්ලිමේන්තුව & නීති සම්පාදනය) ---

  // --- SET 4: විධායකය (ජනාධිපති & අමාත්‍ය මණ්ඩලය) ---

  // --- SET 5: අධිකරණය & අධිකරණයේ ස්වාධීනත්වය ---
  private val set5_Grade10 = listOf(
    CardContentTuple("අධිකරණය (Judiciary) යනු කුමක්ද? එහි ප්‍රධාන කාර්යය කුමක්ද?", "නීතිය අර්ථ නිරූපණය කිරීම, නීතිය උල්ලංඝනය කරන අයට දඬුවම් නියම කිරීම සහ ආරවුල් සාමකාමීව විසඳන රාජ්‍යයේ ත්‍රිවිධ අංශයෙන් තෙවැන්නයි.", "යුක්තිය පසිඳලීමේ පරම ස්ථානයයි.", "නීතිය අර්ථ නිරූපණය & යුක්තිය පසිඳලීම"),
    CardContentTuple("ශ්‍රී ලංකාවේ උසාවි පද්ධතියේ ιεරාර්කිය (පහළ සිට ඉහළට) දක්වන්න.", "1. ප්‍රාථමික / මහේස්ත්‍රාත් සහ දිසා අධිකරණ\n2. පළාත් මහාධිකරණ\n3. අභියාචනාධිකරණය (Court of Appeal)\n4. ශ්‍රේෂ්ඨාධිකරණය (Supreme Court - ඉහළම අධිකරණය).", "අභියාචනා ක්‍රමවේදයක් ඔස්සේ ඉහළට යයි.", "මහේස්ත්‍රාත් -> දිසා -> මහා -> අභියාචනා -> ශ්‍රේෂ්ඨ"),
